uniform float speed : 0.0 .. 5.0 = 0.8;
uniform float scale : 0.02 .. 2.0 = 1.0;
uniform float swell : 0.0 .. 1.0 = 0.6;
uniform vec3 deep : color = 0.02, 0.08, 0.20;
uniform vec3 crest : color = 0.30, 0.60, 0.95;
uniform vec3 foam : color = 0.90, 0.95, 1.00;

state fixed ph;

void update() {
  ph = fract(ph + fixed(dt * speed * 0.25));
}

vec3 shade(Led led) {
  fixed ang = atan2(fixed(led.pos.z), fixed(led.pos.x)) + fixed(0.5);
  fixed h = sin(fixed(led.pos.y) * fixed(scale) * fixed(6.2832) + ph);
  fixed tide = clamp(h * fixed(1.5) + fixed(0.5), fixed(0.0), fixed(1.0));
  fixed foamEdge = step(tide, fixed(0.5));
  vec3 c = mix(deep, crest, tide);
  c = mix(c, foam, foamEdge * swell);
  return c;
}
